package sonar.calculator.mod.client.model;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/** Exact Techne boxes, UV offsets and pivots from Calculator 1.12 (MIT). Generated by convert_assets_models.py. */
public final class ModelSplit {
    private ModelSplit() {}
    public static LayerDefinition createLayer() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        root.addOrReplaceChild("Split1", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 1.0F, 4.0F, 1.0F), PartPose.offsetAndRotation(-0.5F, 10.0F, -0.5F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Split2", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 3.0F, 1.0F, 3.0F), PartPose.offsetAndRotation(-1.5F, 13.0F, -1.5F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Frame1", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 12.0F, 1.0F, 2.0F), PartPose.offsetAndRotation(-6.0F, 9.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Frame2", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 1.0F, 10.0F, 2.0F), PartPose.offsetAndRotation(-7.0F, 10.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        root.addOrReplaceChild("Frame3", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 1.0F, 10.0F, 2.0F), PartPose.offsetAndRotation(6.0F, 10.0F, -1.0F, 0.0F, 0.0F, 0.0F));
        return LayerDefinition.create(mesh, 64, 32);
    }
    public static void renderSplitter(ModelPart root, PoseStack poses, VertexConsumer vertices, int light, int overlay) {
        root.getChild("Split1").render(poses, vertices, light, overlay);
        root.getChild("Split2").render(poses, vertices, light, overlay);
        root.getChild("Frame1").render(poses, vertices, light, overlay);
    }
    public static void render(ModelPart root, PoseStack poses, VertexConsumer vertices, int light, int overlay) {
        root.getChild("Frame2").render(poses, vertices, light, overlay);
        root.getChild("Frame3").render(poses, vertices, light, overlay);
    }
}
